public class Main {
    static class Clock {
        long time = 0;
        long tick() {
            return ++time;
        }
        long send() {
            return tick();
        }
        long receive(long remote) {
            time = Math.max(time, remote);
            return tick();
        }
    }

    public static void main(String[] args) {
        Clock a = new Clock(), b = new Clock();
        long m1 = a.send();
        a.tick();
        long m2 = a.send();
        b.tick();
        System.out.println("m1=" + m1 + " m2=" + m2);
        System.out.println("b after m1: " + b.receive(m1));
        System.out.println("b after m2: " + b.receive(m2));
        System.out.println("a=" + a.time + " b=" + b.time);
    }
}

