import java.util.*;

public class Main {
    static TreeMap<Integer, String> ring = new TreeMap<>();

    static int h(String s) {
        int x = s.hashCode() * 0x9E3779B1;
        return (x ^ (x >>> 15)) & 0x7fffffff;
    }

    static void addNode(String node, int vnodes) {
        for (int i = 0; i < vnodes; i++) ring.put(h(node + "#" + i), node);
    }

    static String owner(String key) {
        int hk = h(key);
        Map.Entry<Integer, String> e = ring.ceilingEntry(hk);
        if (e == null) {
            e = ring.firstEntry();
        }
        return e.getValue();
    }

    public static void main(String[] args) {
        for (String n : new String[]{"A", "B", "C"}) addNode(n, 50);
        String[] before = new String[3000];
        Map<String, Integer> counts = new TreeMap<>();
        for (int i = 0; i < 3000; i++) {
            before[i] = owner("key" + i);
            counts.merge(before[i], 1, Integer::sum);
        }
        System.out.println("3 nodes: " + counts);
        addNode("D", 50);
        int moved = 0;
        for (int i = 0; i < 3000; i++) {
            String now = owner("key" + i);
            if (!now.equals(before[i])) {
                moved++;
                if (!now.equals("D")) System.out.println("unexpected move");
            }
        }
        System.out.println("after adding D, moved " + moved + " of 3000, all to D");
    }
}

public class Main {
    static class Replica {
        String value; long version;
        Replica(String v, long ver) { value = v; version = ver; }
        public String toString() { return value + "@v" + version; }
    }

    static String quorumRead(Replica[] reps, int[] ask) {
        Replica best = null;
        for (int i : ask) {
            if (best == null || reps[i].version > best.version) best = reps[i];
        }
        for (int j : ask) {
            if (reps[j].version < best.version) {
                reps[j].version = best.version;
                reps[j].value = best.value;
            }
        }
        return best.value + "@v" + best.version;
    }

    public static void main(String[] args) {
        Replica[] reps = { new Replica("red", 1), new Replica("red", 1), new Replica("red", 1) };
        // write "blue" v2 with w=2: only replicas 0 and 1 acknowledged
        reps[0].value = "blue"; reps[0].version = 2;
        reps[1].value = "blue"; reps[1].version = 2;
        System.out.println("before: " + java.util.Arrays.toString(reps));
        System.out.println("read r=2 from {1,2}: " + quorumRead(reps, new int[]{1, 2}));
        System.out.println("after:  " + java.util.Arrays.toString(reps));
        System.out.println("read r=1 from {2}: " + quorumRead(reps, new int[]{2}));
    }
}

