public class Main {
    static class Storage {
        long highestToken = 0;
        List<String> log = new ArrayList<>();
        List<String> rejected = new ArrayList<>();
        synchronized boolean write(long token, String data) {
            if (token < highestToken) {
                rejected.add(data + "#" + token);
                return false;
            }
            highestToken = token;
            log.add(data + "#" + token);
            return true;
        }
    }

    public static void main(String[] args) {
        Storage s = new Storage();
        long t1 = 33;                 // client 1 acquires the lease
        s.write(t1, "c1-a");
        // client 1 hits a long GC pause, its lease expires
        long t2 = 34;                 // client 2 acquires the lease
        s.write(t2, "c2-a");
        s.write(t1, "c1-b");          // client 1 wakes up, still thinks it is leader
        s.write(t2, "c2-b");
        System.out.println("accepted: " + s.log);
        System.out.println("rejected: " + s.rejected);
    }
}

