import java.util.Arrays;

public class Main {
    static String compare(int[] a, int[] b) {
        boolean aLess = false, bLess = false;
        for (int i = 0; i < a.length; i++) {
            if (a[i] < b[i]) aLess = true;
            if (a[i] > b[i]) bLess = true;
        }
        if (aLess && bLess) return "concurrent";
        if (aLess) return "before";
        if (bLess) return "after";
        return "equal";
    }

    static int[] merge(int[] a, int[] b) {
        int[] m = new int[a.length];
        for (int i = 0; i < a.length; i++)
            m[i] = Math.max(a[i], b[i]);
        return m;
    }

    public static void main(String[] args) {
        int[] x = {2, 0, 0};
        int[] y = {2, 1, 0};
        int[] z = {3, 0, 0};
        System.out.println("x vs y: " + compare(x, y));
        System.out.println("y vs z: " + compare(y, z));
        System.out.println("z vs x: " + compare(z, x));
        int[] m = merge(y, z);
        System.out.println("merge(y,z) = " + Arrays.toString(m));
        System.out.println("y vs merged: " + compare(y, m));
        System.out.println("m vs m: " + compare(m, m));
    }
}

