import java.util.*;

public class Main {
    static Map<String, Long> lastBeat = new TreeMap<>();

    static void onHeartbeat(String node, long now) {
        lastBeat.put(node, now);
    }

    static List<String> suspects(long now, long timeout) {
        List<String> out = new ArrayList<>();
        for (var e : lastBeat.entrySet()) {
            if (now - e.getValue() > timeout) out.add(e.getKey());
        }
        return out;
    }

    public static void main(String[] args) {
        // MongoDB-like: heartbeat every 2000ms, electionTimeoutMillis 10000
        for (long t = 0; t <= 20000; t += 2000) {
            onHeartbeat("secondary-1", t);
            if (t <= 6000) onHeartbeat("primary", t);
            if (t % 4000 == 0) onHeartbeat("secondary-2", t);
        }
        for (long now : new long[]{12000, 16001, 20000}) {
            System.out.println("t=" + now + " suspects=" + suspects(now, 10000));
        }
    }
}

public class Main {
    static class Node {
        long currentTerm, lastLogTerm, lastLogIndex;
        String votedFor;

        Node(long term, long llt, long lli) {
            currentTerm = term; lastLogTerm = llt; lastLogIndex = lli;
        }

        boolean requestVote(long term, String cand, long cLastTerm, long cLastIndex) {
            if (term < currentTerm) return false;
            if (term > currentTerm) {
                currentTerm = term;
                votedFor = null;
            }
            boolean upToDate = cLastTerm > lastLogTerm
                || (cLastTerm == lastLogTerm && cLastIndex >= lastLogIndex);
            if (upToDate && (votedFor == null || votedFor.equals(cand))) {
                votedFor = cand;
                return true;
            }
            return false;
        }
    }

    public static void main(String[] args) {
        Node n = new Node(5, 5, 10);
        System.out.println("old term 4, x:      " + n.requestVote(4, "x", 5, 20));
        System.out.println("term 6, a stale log: " + n.requestVote(6, "a", 5, 9));
        System.out.println("term 6, b fresh:     " + n.requestVote(6, "b", 5, 10));
        System.out.println("term 6, b again:     " + n.requestVote(6, "b", 5, 10));
        System.out.println("term 6, c fresher:   " + n.requestVote(6, "c", 6, 1));
        System.out.println("term 7, c fresher:   " + n.requestVote(7, "c", 6, 1));
        System.out.println("term=" + n.currentTerm + " votedFor=" + n.votedFor);
    }
}

import java.util.*;

public class Main {
    record Event(long seq, String payload) {}

    static List<Event> outbox = new ArrayList<>();
    static List<String> broker = new ArrayList<>();
    static long resumeToken = 0;   // persisted alongside the relay

    static void relay(int maxBatch) {
        int published = 0;
        for (Event e : outbox) {
            if (e.seq() <= resumeToken) continue;
            if (published == maxBatch) return;
            broker.add(e.payload());
            published++;
            resumeToken = e.seq();
        }
    }

    public static void main(String[] args) {
        // business write and outbox insert happen in one local transaction
        for (int i = 1; i <= 5; i++) outbox.add(new Event(i, "order-" + i));
        relay(2);
        System.out.println("batch 1: " + broker + " token=" + resumeToken);
        relay(2);
        System.out.println("batch 2: " + broker + " token=" + resumeToken);
        outbox.add(new Event(6, "order-6"));
        relay(10);
        System.out.println("batch 3: " + broker + " token=" + resumeToken);
        relay(10);
        System.out.println("idle:    " + broker.size() + " events, token=" + resumeToken);
    }
}

