public class Main {
    record Write(String value, long ts, String node) {}

    static Write lww(Write x, Write y) {
        if (x.ts() != y.ts())
            return x.ts() > y.ts() ? x : y;
        return x.node().compareTo(y.node()) > 0 ? x : y;
    }

    public static void main(String[] args) {
        long skewA = 100;  // node A's clock runs 100ms fast
        // real time 1000: A writes v1
        Write w1 = new Write("v1", 1000 + skewA, "A");
        // real time 1050: B reads v1, then writes v2 (causally after v1)
        Write w2 = new Write("v2", 1050, "B");
        System.out.println("winner: " + lww(w1, w2).value() + " (v2 was written later)");
        System.out.println("order-independent: " + lww(w2, w1).value());
        Write t1 = new Write("x", 2000, "A"), t2 = new Write("y", 2000, "B");
        System.out.println("tie: " + lww(t1, t2).value() + " / " + lww(t2, t1).value());
    }
}

