public class Main {
    static long primary = 0, secondary = 0;
    static List<long[]> oplog = new ArrayList<>();

    static void primaryInc(long delta) {
        primary += delta;
        // entry = {ts, field value}
        oplog.add(new long[]{oplog.size() + 1, primary});
