    public static void main(String[] args) {
        primaryInc(5);
        primaryInc(3);
        primaryInc(2);
        for (long[] e : oplog) apply(e);
        System.out.println("after first apply: primary=" + primary + " secondary=" + secondary);
        // crash: secondary restarts from an older checkpoint and replays from ts 2
