import java.util.*;

public class Main {
    static int compared = 0;

    static long[] build(long[] leaves) {
        int n = leaves.length;
        long[] t = new long[2 * n];
        for (int i = 0; i < n; i++) t[n + i] = leaves[i];
        for (int i = n - 1; i > 0; i--) t[i] = (t[2 * i] * 1_000_003L + t[2 * i + 1]) ^ (i * 7919L);
        return t;
    }

    static void diff(long[] a, long[] b, int node, int n, List<Integer> out) {
        compared++;
        if (a[node] == b[node]) return;
        if (node >= n) {
            out.add(node - n);
            return;
        }
        diff(a, b, 2 * node, n, out);
        diff(a, b, 2 * node + 1, n, out);
    }

    public static void main(String[] args) {
        long[] bucketsA = {11, 22, 33, 44, 55, 66, 77, 88};
        long[] bucketsB = {11, 22, 34, 44, 55, 66, 70, 88};
        long[] ta = build(bucketsA), tb = build(bucketsB);
        List<Integer> out = new ArrayList<>();
        diff(ta, tb, 1, 8, out);
        System.out.println("buckets to sync: " + out);
        System.out.println("nodes compared: " + compared + " of " + (2 * 8 - 1));
        compared = 0;
        out.clear();
        diff(ta, build(bucketsA.clone()), 1, 8, out);
        System.out.println("identical replicas: " + out + " after " + compared + " comparison");
    }
}

