import java.util.*;

public class Main {
    static class Node {
        long optime = 0; String value = "none";
        Deque<Object[]> pending = new ArrayDeque<>();
        List<Node> followers = new ArrayList<>();
        long write(String v) {
            optime++; value = v;
            for (Node f : followers) f.pending.add(new Object[]{optime, v});
            return optime;
        }
        void applyNext() {
            Object[] e = pending.poll();
            optime = (Long) e[0]; value = (String) e[1];
            System.out.println("  secondary waits, applies optime " + optime);
        }
    }

    static long sessionTime = 0;

    static void write(Node primary, String v) {
        long op = primary.write(v);
        sessionTime = Math.max(sessionTime, op);
    }

    static String readCausal(Node n) {
        while (n.optime < sessionTime) n.applyNext();
        sessionTime = Math.max(sessionTime, n.optime);
        return n.value;
    }

    public static void main(String[] args) {
        Node p = new Node(), s = new Node();
        p.followers.add(s);
        write(p, "v1");
        write(p, "v2");
        write(p, "v3");
        System.out.println("secondary optime before read: " + s.optime);
        System.out.println("causal read -> " + readCausal(s) + " (sessionTime " + sessionTime + ")");
        System.out.println("naive read without waiting would have returned: none");
    }
}
